function renderResearchLabs(hits,q,docHits=[],links=[]){
 const evidence=$('#evidenceLab'),claims=$('#claimsLab'),graph=$('#graphLab'),audit=$('#auditLab');[evidence,claims,graph,audit].forEach(x=>x.innerHTML='');
 const uniqueDocs=[...new Map(docHits.map(h=>[h.d.path,h])).values()];
 evidence.innerHTML='<h3>Laboratorio de evidencia</h3>'+(hits.length?hits.slice(0,6).map(({r,score})=>`<div class="result-card"><strong>${escapeHtml(r.id)} · ${escapeHtml(r.name)}</strong><div class="muted">Registro local · score ${score}</div><div>${escapeHtml(r.formula||'Sin fórmula')} · ${escapeHtml(r.location||'Ubicación no informada')}</div><div class="footer-note">Fuente: ${escapeHtml(r.source||'inventory.json')}</div></div>`).join(''):'<div class="notice">Sin coincidencias directas en el inventario.</div>')+(uniqueDocs.length?`<h3 class="section">Documentos relevantes</h3>`+uniqueDocs.map(h=>`<div class="result-card"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><strong>📄 ${escapeHtml(h.d.name)}</strong><button class="btn" data-open-doc="${escapeHtml(h.d.path)}">Abrir visor</button></div><div class="muted">${escapeHtml(h.d.type)} · mejor coincidencia en fragmento ${h.index+1} · ${h.count||1} coincidencia(s) internas</div><div>${escapeHtml(h.chunk.slice(0,650))}${h.chunk.length>650?'…':''}</div><div class="footer-note">El documento se muestra una sola vez. ${h.count>1?'Hay más coincidencias dentro del mismo archivo, no se duplican en la evidencia.':'No hay más coincidencias en este documento.'}</div></div>`).join(''):'<div class="notice">No hay coincidencias documentales.</div>');
 const claimMap=new Map();hits.slice(0,8).forEach(({r})=>{claimMap.set('i:'+r.id,{text:`${r.id} corresponde a ${r.name}`,type:'directa',source:r.id});if(r.location)claimMap.set('l:'+r.id,{text:`${r.name} está ubicado en ${r.location}`,type:'directa',source:r.id});if(r.formula)claimMap.set('f:'+r.id,{text:`${r.name} tiene fórmula ${r.formula}`,type:'directa',source:r.id});});uniqueDocs.forEach(h=>claimMap.set('d:'+h.d.path,{text:`${h.d.name} contiene evidencia relacionada con la consulta`,type:'documental',source:`${h.d.name} · ${h.count||1} coincidencia(s)`}));claims.innerHTML='<h3>Claims</h3>'+[...claimMap.values()].map(c=>`<div class="result-card"><strong>${escapeHtml(c.text)}</strong><div class="muted">Tipo: ${escapeHtml(c.type)} · evidencia: ${escapeHtml(c.source)}</div></div>`).join('')||'<div class="notice">No hay claims para esta consulta.</div>';
 const graphData=buildGraphData(hits,uniqueDocs,links);graph.innerHTML='<h3>Grafo NEXUS-X</h3><div class="notice">'+graphData.nodes.length+' nodos · '+graphData.edges.length+' relaciones · '+uniqueDocs.length+' documento(s) únicos. Cada documento aparece una sola vez.</div>';const graphMount=document.createElement('div');graphMount.className='interactive-graph';graph.appendChild(graphMount);renderInteractiveGraph(graphData,graphMount);
 audit.innerHTML='<h3>Auditoría</h3><div class="diagnostic">'+escapeHtml(JSON.stringify({query:q,localFirst:true,inventoryHits:hits.length,uniqueDocuments:uniqueDocs.length,connectedEntities:links.map(x=>x.id),documentsIndexed:state.docs.length,webEnabled:state.web,adversarial:$('#adversarial').checked,steps:['normalización','búsqueda de entidades','búsqueda documental agrupada por archivo','deduplicación de evidencia','grafo interactivo','web opcional'],timestamp:new Date().toISOString()},null,2))+'</div>';
}
function setResearchTab(tab){$$('.research-tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));['evidenceLab','claimsLab','graphLab','auditLab'].forEach(id=>$('#'+id).style.display='none');if(tab==='evidence')$('#evidenceLab').style.display='block';if(tab==='claims')$('#claimsLab').style.display='block';if(tab==='graph')$('#graphLab').style.display='block';if(tab==='audit')$('#auditLab').style.display='block';if(tab==='answer')$('#researchResults').style.display='block';else $('#researchResults').style.display='none';}
function runResearch(){const q=$('#researchInput').value.trim();if(!q){toast('Escribí una consulta.');return}state.lastQuery=q;saveQueryHistory(q);const hits=searchLocal(q),docHits=documentSearch(q),links=crossRelations(docHits,hits);$('#researchLocal').innerHTML=(hits.length||docHits.length)?`<strong>${hits.length} entidad(es) · ${docHits.length} evidencia(s) documental(es).</strong> NEXUS-X cruza inventario y archivos locales antes de Internet.`:'No hay coincidencias locales en inventario ni documentos indexados. Podés activar Internet si necesitás contexto externo.';$('#researchResults').innerHTML=hits.map(({r,score})=>`<div class="result-card"><strong>${escapeHtml(r.name)} <span class="id">${escapeHtml(r.id)}</span></strong><div class="muted">${escapeHtml(r.formula||'Sin fórmula')} · ${escapeHtml(r.physicalState||'—')} · ${escapeHtml(r.location||'—')}</div><div class="footer-note">Puntaje local: ${score}</div><button class="btn section" data-result-id="${escapeHtml(r.id)}">Ver ficha</button></div>`).join('')+(docHits.length?`<h3 class="section">Evidencia documental</h3>`+docHits.slice(0,8).map(h=>`<div class="result-card"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><strong>📄 ${escapeHtml(h.d.name)}</strong><button class="btn" data-open-doc="${escapeHtml(h.d.path)}">Abrir visor</button></div><div class="muted">${escapeHtml(h.d.type)} · mejor fragmento ${h.index+1}${h.count>1?` · ${h.count} coincidencias en este mismo documento`:''}</div><div>${escapeHtml(h.chunk.slice(0,700))}${h.chunk.length>700?'…':''}</div><div class="footer-note">${h.d.relations?.filter(r=>links.some(x=>x.id===r.entityId)).slice(0,5).map(r=>escapeHtml(r.entityId+' · '+r.entityName)).join(' · ')||'Sin entidad directa detectada'}</div></div>`).join(''):'');$$('[data-result-id]').forEach(b=>b.addEventListener('click',()=>openItem(b.dataset.resultId)));$$('[data-open-doc]').forEach(b=>b.onclick=()=>openDocumentViewer(b.dataset.openDoc));renderResearchLabs(hits,q,docHits,links);setResearchTab('answer');if(state.web)runWeb(q);else $('#webResults').innerHTML='';$('#chat').innerHTML=`<div class="msg bot">Contexto local preparado: ${hits.length} entidad(es) y ${docHits.length} fragmento(s) documental(es). Las respuestas deben distinguir evidencia, inferencia y contexto externo.</div>`;}
async function fetchTimeout(url,options={},ms=WEB_TIMEOUT){const c=new AbortController();const t=setTimeout(()=>c.abort(),ms);try{return await fetch(url,{...options,signal:c.signal})}finally{clearTimeout(t)}}
async function searchWebSources(q){const providers=[['DuckDuckGo','https://api.duckduckgo.com/?q='+encodeURIComponent(q)+'&format=json&no_html=1&skip_disambig=1'],['Jina Reader','https://r.jina.ai/http://www.google.com/search?q='+encodeURIComponent(q)]];for(const [name,url] of providers){try{const res=await fetchTimeout(url,{headers:{Accept:'application/json,text/plain'}},WEB_TIMEOUT);if(!res.ok)throw new Error('HTTP '+res.status);const text=await res.text();const parsed=name==='DuckDuckGo'?parseDDG(JSON.parse(text)):parseJina(text);if(parsed.length)return {provider:name,results:parsed.slice(0,8)}}catch(e){console.warn(name,e)}}return {provider:'',results:[]}}
async function runWeb(q){const box=$('#webResults');box.innerHTML='<div class="notice">🌐 Buscando Internet… si el proveedor falla, NEXUS-X seguirá funcionando localmente.</div>';const out=await searchWebSources(q);if(out.results.length){box.innerHTML=`<div class="notice"><strong>🌐 ${escapeHtml(out.provider)}</strong> · resultados externos (no son evidencia del inventario).</div>`+out.results.map(x=>`<div class="result-card"><strong>${escapeHtml(x.title)}</strong><div class="muted">${escapeHtml(x.snippet||'')}</div>${x.url?`<a href="${escapeHtml(x.url)}" target="_blank" rel="noopener noreferrer">Abrir fuente</a>`:''}</div>`).join('');return out}box.innerHTML='<div class="notice warn">Internet no devolvió resultados en este momento. Esto no afecta la búsqueda local.</div>';return out;}
function parseDDG(d){const out=[];if(d.AbstractText)out.push({title:d.Heading||'Resumen',snippet:d.AbstractText,url:d.AbstractURL});for(const x of (d.RelatedTopics||[])){if(x.Text)out.push({title:x.Text.slice(0,100),snippet:x.Text,url:x.FirstURL})}return out;}
function parseJina(t){const out=[];const lines=t.split(/\n+/).map(x=>x.trim()).filter(Boolean);for(let i=0;i<lines.length&&out.length<12;i++){const m=lines[i].match(/^\[?\d+\]?\s*\.?\s*(.+)$/);if(m&&lines[i+1])out.push({title:m[1],snippet:lines[i+1].slice(0,300),url:(lines[i+2]||'').match(/https?:\/\/\S+/)?.[0]||''})}return out;}
async function loadScript(url,globalName){if(window[globalName])return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=()=>reject(new Error('No se pudo cargar '+url));document.head.appendChild(s)})}
async function importExcel(file){try{await loadScript('https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js','XLSX');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,raw:false,defval:''});const rows=[];for(const name of wb.SheetNames){const data=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:''});if(!data.length)continue;let hi=0,best=-1;data.slice(0,12).forEach((row,i)=>{const s=row.map(norm).join(' ');const score=row.filter(Boolean).length+(/(id|codigo|nombre|material|sustancia|formula|ubicacion|stock)/.test(s)?8:0);if(score>best){best=score;hi=i}});const headers=data[hi].map((x,i)=>String(x||`Campo ${i+1}`).trim());for(let i=hi+1;i<data.length;i++){const raw={};headers.forEach((h,j)=>raw[h]=data[i][j]??'');if(Object.values(raw).some(v=>String(v).trim()))rows.push(raw)}}if(!rows.length)throw new Error('No se encontraron filas.');const mapped=rows.map((r,i)=>{const keys=Object.keys(r);const pick=(...names)=>{const k=keys.find(k=>names.includes(norm(k)));return k?r[k]:''};return normalizeRecord({id:pick('id nexus x','id_nexus_x','id','codigo nexus','codigo'),originalNumber:pick('nº original','n° original','numero original','nro original'),name:pick('sustancia mezcla material','sustancia','mezcla','material','nombre','descripcion'),formula:pick('formula','fórmula','formula quimica','fórmula química'),physicalState:pick('estado fisico','estado físico'),presentation:pick('presentacion','presentación'),originalPackage:pick('envase original'),expiry:pick('fecha envasado vencimiento','vencimiento','fecha vencimiento'),location:pick('ubicacion armario','ubicación armario','ubicacion','ubicación','estante'),notes:pick('observaciones','notas','comments')},i+1)});let generated=0;const used=new Set(mapped.filter(r=>validId(r.id)).map(r=>r.id));let next=1;mapped.forEach(r=>{if(!validId(r.id)){while(used.has(`NEXUS-X-${String(next).padStart(4,'0')}`))next++;r.id=`NEXUS-X-${String(next).padStart(4,'0')}`;used.add(r.id);next++;generated++}});validateInventory(mapped,null);state.inventory=mapped;saveInventory();saveActivity(`Excel importado: ${mapped.length} filas · ${generated} IDs normalizados`);renderAll();toast(`Excel cargado: ${mapped.length} registros.`)}catch(e){console.error(e);toast('No se importó el Excel: '+e.message)}}
async function importWord(file){try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js','JSZip');const zip=await JSZip.loadAsync(await file.arrayBuffer());const xml=await zip.file('word/document.xml').async('text');const doc=new DOMParser().parseFromString(xml,'application/xml');const texts=[...doc.getElementsByTagName('w:p')].map(p=>[...p.getElementsByTagName('w:t')].map(t=>t.textContent||'').join('').trim()).filter(Boolean);const text=texts.join('\n');const blocks=text.split(/(?=REGISTRO\s+\d+)/).slice(1);const labels=['ID_NEXUS_X','Nº_Original','Sustancia_Mezcla_Material','Formula','Estado_Fisico','Presentacion','Envase_Original','Fecha_Envasado_Vencimiento','Ubicacion_Armario'];const re=new RegExp('('+labels.map(x=>x.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')).join('|')+')\\s*:\\s*([\\s\\S]*?)(?=\\s+(?:'+labels.join('|')+')\\s*:|$)','g');const records=[];for(const b of blocks){const mm=b.match(/^REGISTRO\s+(\d+)/);if(!mm)continue;const o={record:Number(mm[1])};let m;while((m=re.exec(b))){o[m[1]]=(m[2]||'').replace(/\s+/g,' ').trim()}re.lastIndex=0;records.push(normalizeRecord(o,records.length+1))}validateInventory(records,111);state.inventory=records;saveInventory();const d=await indexDocxDocument(file);const gh=await githubUploadDocument(file);if(gh.ok){await deleteDoc(d.path);const url=`https://raw.githubusercontent.com/${REPO_OWNER}/${REPO_NAME}/${REPO_BRANCH}/${gh.path.split('/').map(encodeURIComponent).join('/')}`;await indexDocument({name:file.name,path:gh.path,type:'DOCX',size:file.size,text:d.text,source:'GitHub',url,blob:file,mime:file.type||'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});saveActivity('Word maestro cargado, validado y guardado en GitHub')}else saveActivity('Word maestro cargado e indexado localmente');renderAll();toast(gh.ok?'Word maestro validado y guardado en GitHub.':'Word maestro validado; quedó local hasta configurar GitHub.')}catch(e){console.error(e);toast('Word rechazado; se conservó la base anterior. '+e.message)}}
function qrExtractId(raw){const text=String(raw??'').trim();const m=text.match(/(?:NEXUS[-_:]?X|NX)[-_: ]*(\d{1,6})/i);return m?`NEXUS-X-${String(Number(m[1])).padStart(4,'0')}`:canonicalId(text.replace(/[?#].*$/,'').replace(/\/+$/,''));}
async function loadQrFallback(){await loadScript('https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js','jsQR');}
async function decodeQrImage(file){try{if('BarcodeDetector' in window){const bitmap=await createImageBitmap(file);const detector=new BarcodeDetector({formats:['qr_code']});const codes=await detector.detect(bitmap);bitmap.close();if(codes[0]?.rawValue){processQr(codes[0].rawValue);return}}await loadQrFallback();const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const img=ctx.getImageData(0,0,canvas.width,canvas.height);const code=window.jsQR(img.data,img.width,img.height,{inversionAttempts:'attemptBoth'});if(!code?.data)throw new Error('No se detectó un QR en la imagen.');processQr(code.data)}catch(e){console.error(e);toast('No se pudo leer el QR: '+e.message)}}
async function startQr(){if(!navigator.mediaDevices?.getUserMedia){toast('La cámara no está disponible en este navegador/contexto. Usá HTTPS o carga un ID manual.');return}stopQr();try{state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});const v=$('#qrVideo');v.srcObject=state.stream;await v.play();$('#qrStage').classList.remove('black');$('#qrStageText').textContent='Buscando código…';if('BarcodeDetector' in window){const detector=new BarcodeDetector({formats:['qr_code']});state.scanBusy=false;const loop=async()=>{if(!state.stream||state.scanBusy)return;try{const codes=await detector.detect(v);if(codes[0]?.rawValue){state.scanBusy=true;processQr(codes[0].rawValue);return}}catch(e){}requestAnimationFrame(loop)};requestAnimationFrame(loop)}else{try{await loadQrFallback();}catch(e){$('#qrStageText').textContent='Escáner automático no disponible. Usá imagen o ID manual.';return}const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d',{willReadFrequently:true});state.scanBusy=false;const loop=()=>{if(!state.stream||state.scanBusy)return;try{if(v.readyState>=2){canvas.width=v.videoWidth||640;canvas.height=v.videoHeight||480;ctx.drawImage(v,0,0,canvas.width,canvas.height);const img=ctx.getImageData(0,0,canvas.width,canvas.height);const code=window.jsQR(img.data,img.width,img.height,{inversionAttempts:'attemptBoth'});if(code?.data){state.scanBusy=true;processQr(code.data);return}}}catch(e){}requestAnimationFrame(loop)};requestAnimationFrame(loop)}}catch(e){console.error(e);toast('No se pudo iniciar la cámara: '+e.message)}}
function stopQr(){if(state.stream){state.stream.getTracks().forEach(t=>t.stop());state.stream=null}state.scanBusy=false;const v=$('#qrVideo');if(v)v.srcObject=null;$('#qrStage')?.classList.add('black');if($('#qrStageText'))$('#qrStageText').textContent='Cámara detenida'}
function processQr(raw){const id=qrExtractId(raw);const r=state.inventory.find(x=>x.id===id);stopQr();$('#qrStage').classList.add('black');if(r){$('#qrResult').innerHTML=`<div class="notice"><strong>${escapeHtml(r.id)}</strong><br>${escapeHtml(r.name)}<br><span class="muted">${escapeHtml(r.formula||'Sin fórmula')} · ${escapeHtml(r.location||'Sin ubicación')}</span></div><button class="btn primary section" id="qrOpenResult">Abrir ficha</button>`;$('#qrOpenResult').onclick=()=>openItem(r.id);saveActivity(`QR leído: ${r.id}`)}else $('#qrResult').innerHTML=`<div class="notice warn">Código detectado: <strong>${escapeHtml(id||raw)}</strong><br>No existe un registro con ese ID.</div>`;}
async function importPdf(file){return importDocumentFile(file)}
async function importDocumentFile(file){
  try{
    const result=await githubUploadDocument(file);
    if(result.ok){
      const localPath='local:'+file.name;
      const d=await indexLocalFile(file);
      await deleteDoc(localPath);
      await deleteDoc(d.path);
      const url=`https://raw.githubusercontent.com/${REPO_OWNER}/${REPO_NAME}/${REPO_BRANCH}/${result.path.split('/').map(encodeURIComponent).join('/')}`;
      await indexDocument({name:file.name,path:result.path,type:d.type,size:file.size,text:d.text,source:'GitHub',url,blob:file,mime:file.type});
      saveActivity(`Documento guardado en GitHub: ${file.name}`);toast(`✓ ${file.name} guardado en GitHub y persistido.`);return;
    }
    const d=await indexLocalFile(file);
    saveActivity(`Documento indexado localmente: ${file.name}`);
    if(result.needsToken)toast(`Documento guardado localmente. Configurá GitHub una sola vez en Ajustes y NEXUS-X lo sincronizará.`);
    else toast(`Documento local guardado, pero GitHub no respondió: ${result.message}`);
  }catch(e){console.error(e);toast('No se pudo procesar el documento: '+e.message)}
}
async function syncPendingLocalDocuments(){
  const pending=state.docs.filter(d=>String(d.path||'').startsWith('local:')&&d.blob instanceof Blob);
  let done=0;
  for(const d of pending){
    try{
      const result=await githubUploadDocument(new File([d.blob],d.name,{type:d.mime||d.blob.type||'application/octet-stream'}));
      if(!result.ok)continue;
      const url=`https://raw.githubusercontent.com/${REPO_OWNER}/${REPO_NAME}/${REPO_BRANCH}/${result.path.split('/').map(encodeURIComponent).join('/')}`;
      const copy={...d,path:result.path,source:'GitHub',url};
      await deleteDoc(d.path);await putDoc(copy);
      const i=state.docs.findIndex(x=>x.path===d.path);if(i>=0)state.docs[i]=copy;done++;
    }catch(e){console.warn('Pendiente local',d.name,e)}
  }
  if(done){renderDocuments();renderDashboard();saveActivity(`Documentos locales sincronizados con GitHub: ${done}`);toast(`✓ ${done} documento(s) local(es) sincronizado(s) con GitHub.`)}
}

async function resolveGeminiModel(key){const saved=localStorage.getItem(GEMINI_MODEL_KEY);if(saved)return saved;const preferred=[GEMINI_MODEL,GEMINI_FALLBACK_MODEL,'gemini-2.5-flash','gemini-2.5-flash-lite'];try{const res=await fetchTimeout('https://generativelanguage.googleapis.com/v1beta/models',{headers:{'x-goog-api-key':key,Accept:'application/json'}},9000);if(res.ok){const d=await res.json();const names=(d.models||[]).map(m=>String(m.name||'').replace(/^models\//,''));const chosen=preferred.find(x=>names.includes(x))||names.find(x=>/flash/i.test(x)&&/generateContent/.test(JSON.stringify(d.models?.find(m=>String(m.name||'').endsWith(x))||{})));if(chosen){localStorage.setItem(GEMINI_MODEL_KEY,chosen);return chosen}}}catch(e){console.warn('No se pudo detectar modelo Gemini',e)}return GEMINI_MODEL}
async function geminiGenerate({question,context='',useSearch=false,document=null}){const key=localStorage.getItem(GEMINI_KEY)||'';if(!key)throw new Error('API de Gemini no configurada. Pegá la clave una sola vez.');const model=await resolveGeminiModel(key);const parts=[];if(document?.type==='PDF'&&document.blob){const ab=await document.blob.arrayBuffer(),bytes=new Uint8Array(ab);let bin='';for(let i=0;i<bytes.length;i+=32768)bin+=String.fromCharCode(...bytes.subarray(i,i+32768));parts.push({inlineData:{mimeType:document.mime||'application/pdf',data:btoa(bin)}})}parts.push({text:`Sos NEXUS-X. Respondé en español. No inventes datos. Separá evidencia del documento/contexto local, inferencia e información externa. Si no podés verificar algo, decilo.\n\n${document?`DOCUMENTO ACTUAL: ${document.name}\nTipo: ${document.type}\nContenido extraído:\n${document.text.slice(0,90000)}\n\n`:''}${context?`CONTEXTO LOCAL:\n${context}\n\n`:''}CONSULTA:\n${question}`});const body={contents:[{role:'user',parts}],generationConfig:{maxOutputTokens:1400}};let last='';for(const m of [model,GEMINI_FALLBACK_MODEL,'gemini-2.5-flash'].filter((v,i,a)=>v&&!a.slice(0,i).includes(v))){try{const res=await fetchTimeout(`${GEMINI_ENDPOINT}/${m}:generateContent`,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify(body)},18000);if(!res.ok){last=`${m}: HTTP ${res.status}`;continue}const d=await res.json();const answer=(d.candidates||[]).flatMap(c=>c.content?.parts||[]).map(p=>p.text||'').join('').trim();if(answer){localStorage.setItem(GEMINI_MODEL_KEY,m);return {answer,grounded:false,model:m}}last=`${m}: respuesta vacía`}catch(e){last=`${m}: ${e.message||e}`}}throw new Error(last||'No se pudo consultar Gemini.')}
async function testGeminiKey(key){if(!key)return {ok:false,message:'Pegá una API Key.'};try{const model=await resolveGeminiModel(key);const res=await fetchTimeout(`${GEMINI_ENDPOINT}/${model}:generateContent`,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify({contents:[{role:'user',parts:[{text:'Respondé solamente: OK'}]}],generationConfig:{maxOutputTokens:8}})},12000);if(!res.ok)return {ok:false,message:`La clave fue rechazada o no tiene acceso a ${model} (HTTP ${res.status}).`};localStorage.setItem(GEMINI_MODEL_KEY,model);return {ok:true,message:`Conectado · ${model}`}}catch(e){return {ok:false,message:e.message||'No se pudo comprobar la clave.'}}}
async function aiQuery(){const q=$('#aiInput').value.trim();if(!q)return;const key=localStorage.getItem(GEMINI_KEY)||'';$('#chat').insertAdjacentHTML('beforeend',`<div class="msg user">${escapeHtml(q)}</div>`);$('#aiInput').value='';if(!key){$('#chat').insertAdjacentHTML('beforeend','<div class="msg bot">IA no configurada. En Ajustes pegá la API Key una sola vez.</div>');return}const hits=searchLocal(state.lastQuery||q).slice(0,8),docs=documentSearch(state.lastQuery||q).slice(0,6);let context=[...hits.map(x=>`${x.r.id} | ${x.r.name} | ${x.r.formula||''} | ${x.r.location||''}`),...docs.map(h=>`DOCUMENTO ${h.d.name}: ${h.chunk.slice(0,2200)}`)].join('\n');const useSearch=/actualiz|actualizado|actualidad|hoy|reciente|vigente|internet|web|fuera del documento/i.test(q);let webNote='';if(useSearch){const web=await searchWebSources(q);if(web.results.length){context+=`\n\nFUENTES WEB EXTERNAS (${web.provider}):\n`+web.results.map(x=>`${x.title}\n${x.snippet}\n${x.url||''}`).join('\n\n');webNote='🌐 Se contrastó con fuentes web externas.'}else webNote='⚠️ No se pudo verificar en Internet; la respuesta queda limitada al contexto local/documental.'}try{const out=await geminiGenerate({question:q,context,useSearch:false});$('#chat').insertAdjacentHTML('beforeend',`<div class="msg bot">${escapeHtml(out.answer)}<div class="footer-note">${webNote||'📚 Respuesta basada en el contexto local/documental.'}</div></div>`)}catch(e){$('#chat').insertAdjacentHTML('beforeend',`<div class="msg bot">No se pudo consultar Gemini: ${escapeHtml(e.message)}. La búsqueda local y documental sigue disponible.</div>`)}$('#chat').scrollTop=$('#chat').scrollHeight;}

function exportCsv(){const headers=['ID_NEXUS_X','Nº_Original','Sustancia_Mezcla_Material','Formula','Estado_Fisico','Presentacion','Envase_Original','Fecha_Envasado_Vencimiento','Ubicacion_Armario','Observaciones'];const map=r=>[r.id,r.originalNumber,r.name,r.formula,r.physicalState,r.presentation,r.originalPackage,r.expiry,r.location,r.notes];const csv=[headers,...state.inventory.map(map)].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');download('NEXUS-X-inventario.csv',new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));}
