async function syncRepository(){const status=$('#repoStatus');status.textContent='Descubriendo archivos…';state.docSyncing=true;renderDocuments();try{const apiBase=`https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}`;const treeRes=await fetchTimeout(`${apiBase}/git/trees/${encodeURIComponent(REPO_BRANCH)}?recursive=1`,{headers:{Accept:'application/vnd.github+json'}},WEB_TIMEOUT);if(!treeRes.ok)throw new Error('GitHub HTTP '+treeRes.status);const tree=await treeRes.json(),files=(tree.tree||[]).filter(x=>x.type==='blob'),supported=files.filter(x=>/\.(pdf|docx|xlsx|xls|csv|txt|md)$/i.test(x.path)&&Number(x.size||0)<=DOC_MAX_BYTES);let ok=0,failed=[];status.textContent=`${supported.length} documentos detectados · indexando…`;for(const f of supported){try{const url=`https://raw.githubusercontent.com/${REPO_OWNER}/${REPO_NAME}/${REPO_BRANCH}/${f.path.split('/').map(encodeURIComponent).join('/')}`,res=await fetchTimeout(url,{},WEB_TIMEOUT);if(!res.ok)throw new Error(`HTTP ${res.status}`);const blob=await res.blob(),type=docType(f.path);let text='';if(type==='DOCX')text=(await JSZipReady(blob)).text;else if(type==='PDF'){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js','pdfjsLib');const pdf=await pdfjsLib.getDocument({data:await blob.arrayBuffer()}).promise,pages=[];for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),content=await page.getTextContent();pages.push(`PÁGINA ${n}\n`+content.items.map(x=>x.str||'').join(' '))}text=pages.join('\n\n')}else if(type==='XLSX'||type==='XLS'){await loadScript('https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js','XLSX');const wb=XLSX.read(await blob.arrayBuffer(),{type:'array',cellDates:true,raw:false,defval:''});text=wb.SheetNames.map(name=>`HOJA: ${name}\n`+XLSX.utils.sheet_to_csv(wb.Sheets[name])).join('\n\n')}else text=await blob.text();await indexDocument({name:f.path.split('/').pop(),path:f.path,type,size:f.size,text,source:'GitHub',url,mime:blob.type,blob});ok++}catch(e){failed.push(`${f.path}: ${e.message||e}`)}}state.docSyncing=false;renderDocuments();status.textContent=`OK · ${ok}/${supported.length} documentos indexados${failed.length?' · '+failed.length+' con error':''}`;if(failed.length)status.title=failed.join('\n');saveActivity(`Repositorio indexado: ${ok}/${supported.length} documentos`);renderDashboard();if(failed.length)toast(`Se indexaron ${ok}/${supported.length}. Hay ${failed.length} archivo(s) con error.`)}catch(e){state.docSyncing=false;status.textContent='No disponible';renderDocuments();toast('No se pudo sincronizar GitHub. NEXUS-X sigue funcionando localmente.')}}
async function JSZipReady(blob){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js','JSZip');const zip=await JSZip.loadAsync(await blob.arrayBuffer());const xml=await zip.file('word/document.xml').async('text');const doc=new DOMParser().parseFromString(xml,'application/xml');const text=[...doc.getElementsByTagName('w:p')].map(p=>[...p.getElementsByTagName('w:t')].map(t=>t.textContent||'').join('').trim()).filter(Boolean).join('\n');return {text}}
let activeDocument=null;async function openDocumentViewer(path){const d=state.docs.find(x=>x.path===path)||await getCachedDocs().then(a=>a.find(x=>x.path===path));if(!d){toast('Documento no disponible en el caché local.');return}activeDocument=d;$('#documentViewerTitle').textContent=d.name;$('#documentViewerMeta').textContent=`${d.type} · ${d.source||'local'} · ${d.chunks?.length||0} fragmentos`;$('#documentViewerAI').classList.remove('open');$('#documentViewerBody').innerHTML='<div class="notice">Abriendo documento…</div>';$('#documentViewerModal').classList.add('open');if(d.type==='PDF'&&d.blob){await renderPdfViewer(d,$('#documentViewerBody'))}else{$('#documentViewerBody').innerHTML=`<pre class="doc-text">${escapeHtml(d.text||'Sin texto extraído.')}</pre>`}}function closeDocumentViewer(){$('#documentViewerModal').classList.remove('open');activeDocument=null}async function renderPdfViewer(d,body){try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js','pdfjsLib');const pdf=await pdfjsLib.getDocument({data:await d.blob.arrayBuffer()}).promise;body.innerHTML='';for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),vp=page.getViewport({scale:1.15}),wrap=document.createElement('div');wrap.className='pdf-page';const canvas=document.createElement('canvas');canvas.width=Math.ceil(vp.width);canvas.height=Math.ceil(vp.height);wrap.appendChild(canvas);body.appendChild(wrap);await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise}}catch(e){body.innerHTML=`<div class="notice error">No se pudo renderizar el PDF dentro de NEXUS-X: ${escapeHtml(e.message)}</div><pre class="doc-text">${escapeHtml(d.text||'')}</pre>`}}async function askDocumentAI(){const q=$('#documentAIInput').value.trim();if(!q||!activeDocument)return;const chat=$('#documentAIChat');chat.insertAdjacentHTML('beforeend',`<div class="msg user">${escapeHtml(q)}</div>`);$('#documentAIInput').value='';if(!localStorage.getItem(GEMINI_KEY)){chat.insertAdjacentHTML('beforeend','<div class="msg bot">Pegá la API Key de Gemini una sola vez en Ajustes.</div>');return}const useSearch=/actualiz|actualizado|actualidad|hoy|reciente|vigente|internet|web|fuera del documento/i.test(q);let context='';let webNote='';if(useSearch){const web=await searchWebSources(q);if(web.results.length){context=`FUENTES WEB EXTERNAS (${web.provider}):\n`+web.results.map(x=>`${x.title}\n${x.snippet}\n${x.url||''}`).join('\n\n');webNote='🌐 Se contrastó con fuentes web externas.'}else webNote='⚠️ No se pudo verificar en Internet; la respuesta queda limitada al documento abierto.'}try{const out=await geminiGenerate({question:q,document:activeDocument,context,useSearch:false});chat.insertAdjacentHTML('beforeend',`<div class="msg bot">${escapeHtml(out.answer)}<div class="footer-note">${webNote||'📄 Respuesta basada en el documento abierto.'}</div></div>`)}catch(e){chat.insertAdjacentHTML('beforeend',`<div class="msg bot">No se pudo consultar Gemini: ${escapeHtml(e.message)}. El documento sigue disponible para lectura local.</div>`)}chat.scrollTop=chat.scrollHeight}function renderGeminiSettings(){const key=localStorage.getItem(GEMINI_KEY)||'';const model=localStorage.getItem(GEMINI_MODEL_KEY)||'detección automática';const input=$('#aiKey');if(input)input.value=key;const status=$('#geminiStatus');if(status)status.innerHTML=key?`<span class="status-dot"></span>Clave guardada · ${escapeHtml(model)} · sin configuración manual`:'<span class="status-dot" style="background:#d89632"></span>Sin clave configurada'}
function renderGithubSettings(){const token=githubToken();const input=$('#githubToken');if(input)input.value=token;const status=$('#githubStatus');if(status)status.innerHTML=token?`<span class="status-dot"></span>GitHub conectado · ${escapeHtml(REPO_OWNER+'/'+REPO_NAME)} · guardado localmente`:'<span class="status-dot" style="background:#d89632"></span>Sin conexión de escritura · los documentos solo quedan locales'}
const CAL_KEY='nexus_x_calendar_v1';let calCursor=new Date();
function calendarEvents(){try{return JSON.parse(localStorage.getItem(CAL_KEY)||'[]')}catch{return[]}}
