function pad2(n){return String(n).padStart(2,'0')}
function isoDate(d){return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`}
function renderCalendar(){const y=calCursor.getFullYear(),m=calCursor.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),start=(first.getDay()+6)%7;const events=calendarEvents();$('#calTitle').textContent=new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(first).replace(/^./,c=>c.toUpperCase());const heads=['L','M','M','J','V','S','D'];let html=heads.map(x=>`<div class="dow">${x}</div>`).join('');for(let i=0;i<start;i++)html+='<div class="day muted-day"></div>';for(let d=1;d<=last.getDate();d++){const date=new Date(y,m,d),key=isoDate(date),dayEvents=events.filter(e=>e.date===key);html+=`<button type="button" class="day ${key===isoDate(new Date())?'today ':''}${dayEvents.length?'has-event':''}" data-cal-date="${key}"><span class="num">${d}</span>${dayEvents.slice(0,2).map(e=>`<span class="dot">• ${escapeHtml(e.text)}</span>`).join('')}</button>`}const total=Math.ceil((start+last.getDate())/7)*7;for(let i=start+last.getDate();i<total;i++)html+='<div class="day muted-day"></div>';$('#calGrid').innerHTML=html;$$('[data-cal-date]').forEach(b=>b.onclick=()=>{$('#calDate').value=b.dataset.calDate;$('#calEvent').focus();});const grouped=events.filter(e=>e.date>=isoDate(new Date(y,m,1))&&e.date<=isoDate(last)).sort((a,b)=>a.date.localeCompare(b.date));$('#calEvents').innerHTML=grouped.length?grouped.map((e,i)=>`<div class="calendar-event"><span><strong>${escapeHtml(e.date)}</strong> · ${escapeHtml(e.text)}</span><button class="btn danger" data-cal-delete="${i}">Eliminar</button></div>`).join(''):'Sin eventos para este mes.';$$('[data-cal-delete]').forEach((b)=>b.onclick=()=>{const target=grouped[Number(b.dataset.calDelete)];saveCalendarEvents(events.filter(e=>!(e.date===target.date&&e.text===target.text)));renderCalendar()})}
function openCalendar(){calCursor=new Date();$('#calDate').value=isoDate(calCursor);$('#calEvent').value='';$('#calendarModal').classList.add('open');renderCalendar()}
function addCalendarEvent(){const date=$('#calDate').value,text=$('#calEvent').value.trim();if(!date||!text){toast('Indicá fecha y evento.');return}const events=calendarEvents();events.push({date,text});events.sort((a,b)=>a.date.localeCompare(b.date));saveCalendarEvents(events);$('#calEvent').value='';renderCalendar();saveActivity(`Evento agregado: ${text}`);toast('Evento agregado al calendario.')}

